"use strict";(self.webpackChunkmindstack=self.webpackChunkmindstack||[]).push([["3154"],{1878(e,n,t){t.r(n),t.d(n,{metadata:()=>i,default:()=>u,frontMatter:()=>r,contentTitle:()=>o,toc:()=>d,assets:()=>l});var i=JSON.parse('{"id":"SoftwareEngineering/domain-driven-design","title":"Domain-Driven Design","description":"Domain-Driven Design (DDD) is an approach to building software that models the actual business domain closely, using the language domain experts already use. It\'s especially valuable for complex business logic \u2014 less so for simple CRUD applications.","source":"@site/docs/SoftwareEngineering/07-domain-driven-design.md","sourceDirName":"SoftwareEngineering","slug":"/SoftwareEngineering/domain-driven-design","permalink":"/Mindstack/docs/SoftwareEngineering/domain-driven-design","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":7,"frontMatter":{"title":"Domain-Driven Design","sidebar_label":"Domain-Driven Design","sidebar_position":7},"sidebar":"softwareEngineeringSidebar","previous":{"title":"Design Patterns","permalink":"/Mindstack/docs/SoftwareEngineering/design-patterns"},"next":{"title":"API Design","permalink":"/Mindstack/docs/SoftwareEngineering/api-design"}}'),s=t(4848),a=t(8453);let r={title:"Domain-Driven Design",sidebar_label:"Domain-Driven Design",sidebar_position:7},o="Domain-Driven Design",l={},d=[{value:"The Core Idea",id:"the-core-idea",level:2},{value:"Ubiquitous Language",id:"ubiquitous-language",level:2},{value:"Bounded Contexts",id:"bounded-contexts",level:2},{value:"Entities vs Value Objects",id:"entities-vs-value-objects",level:2},{value:"Entities \u2014 Defined by Identity",id:"entities--defined-by-identity",level:3},{value:"Value Objects \u2014 Defined by Value",id:"value-objects--defined-by-value",level:3},{value:"Aggregates",id:"aggregates",level:2},{value:"Domain Services",id:"domain-services",level:2},{value:"When DDD Is (and Isn&#39;t) Worth It",id:"when-ddd-is-and-isnt-worth-it",level:2},{value:"Tips",id:"tips",level:2},{value:"Summary",id:"summary",level:2}];function c(e){let n={code:"code",em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",hr:"hr",li:"li",p:"p",pre:"pre",strong:"strong",ul:"ul",...(0,a.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(n.header,{children:(0,s.jsx)(n.h1,{id:"domain-driven-design",children:"Domain-Driven Design"})}),"\n",(0,s.jsx)(n.p,{children:"Domain-Driven Design (DDD) is an approach to building software that models the actual business domain closely, using the language domain experts already use. It's especially valuable for complex business logic \u2014 less so for simple CRUD applications."}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"the-core-idea",children:"The Core Idea"}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:'Most software failures aren\'t caused by bad code \u2014 they\'re caused by\na MISMATCH between what the business actually needs and what the\nsoftware models. DDD\'s central goal is closing that gap by building\nthe software\'s structure directly around the business domain, using\nthe business\'s own vocabulary.\n\nTraditional approach:\n  Business talks in terms of "orders," "fulfillment," "backorders"\n  Code talks in terms of "records," "rows," "status flags"\n  Every conversation between business and engineering requires translation,\n  and every translation is a chance to introduce a misunderstanding.\n\nDDD approach:\n  Code uses the SAME words the business uses, structured the way the\n  business actually thinks about the problem \u2014 reducing translation\n  loss to nearly zero.\n'})}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"ubiquitous-language",children:"Ubiquitous Language"}),"\n",(0,s.jsx)(n.p,{children:"A shared vocabulary, used consistently by domain experts AND in the code itself \u2014 variable names, class names, and function names all use these exact terms."}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-python",children:'# Without ubiquitous language \u2014 generic, technical terms that require\n# a domain expert to "translate" every time they read the code\nclass Record:\n    def update_status(self, new_status):\n        ...\n\nclass Manager:\n    def process(self, record):\n        ...\n\n# With ubiquitous language \u2014 if the business calls it a "Shipment"\n# that gets "Dispatched," the code says exactly that\nclass Shipment:\n    def dispatch(self):\n        ...\n\nclass FulfillmentService:\n    def process_shipment(self, shipment: Shipment):\n        ...\n'})}),"\n",(0,s.jsxs)(n.p,{children:[(0,s.jsx)(n.strong,{children:"In practice:"})," the ubiquitous language is built collaboratively, in conversation with domain experts (not decided unilaterally by engineers) \u2014 and it's expected to evolve as understanding of the domain deepens. When the business's own terminology changes, the code's naming should follow."]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"bounded-contexts",children:"Bounded Contexts"}),"\n",(0,s.jsx)(n.p,{children:"A large domain is rarely uniform \u2014 the same word can mean genuinely different things in different parts of the business. A Bounded Context is an explicit boundary within which a specific model and its ubiquitous language apply consistently."}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:'Example: an e-commerce company has an "Order" that means different\nthings in different parts of the system:\n\n  Sales Context:\n    Order = a customer\'s intent to purchase \u2014 has pricing, discounts,\n    promotions applied\n\n  Warehouse/Fulfillment Context:\n    Order = a set of physical items to pick, pack, and ship \u2014 has\n    bin locations, packing instructions, no concept of "discount"\n\n  Billing Context:\n    Order = a set of line items to invoice \u2014 has tax jurisdictions,\n    payment terms, no concept of "bin location"\n\nTrying to build ONE "Order" class that serves all three contexts\neither bloats into a God Object (see file 03) trying to hold every\nconcern, or forces contexts to share fields that don\'t actually mean\nthe same thing to each of them.\n\nDDD\'s answer: each Bounded Context gets its OWN model of "Order,"\ntailored to what that context actually needs. They\'re connected via\nexplicit translation at the boundaries (an integration/anti-corruption\nlayer), not by sharing one class across contexts.\n'})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-python",children:"# Sales context \u2014 its own Order model\n@dataclass\nclass SalesOrder:\n    customer_id: str\n    line_items: list\n    discount_applied: float\n    promotion_code: str | None\n\n# Fulfillment context \u2014 a DIFFERENT Order model, same real-world\n# concept, different concerns\n@dataclass\nclass FulfillmentOrder:\n    order_reference: str          # links back to the Sales context\n    items_to_pick: list\n    warehouse_bin_locations: dict\n    packing_instructions: str\n\n# Explicit translation at the boundary \u2014 an anti-corruption layer,\n# so a change in one context's model doesn't ripple uncontrolled\n# into the other\ndef sales_order_to_fulfillment_order(sales_order: SalesOrder) -> FulfillmentOrder:\n    return FulfillmentOrder(\n        order_reference=sales_order.customer_id,\n        items_to_pick=[item.sku for item in sales_order.line_items],\n        warehouse_bin_locations={},\n        packing_instructions=\"\",\n    )\n"})}),"\n",(0,s.jsx)(n.p,{children:"This is the DDD concept that most directly informs microservice boundaries (see file 09 and file 10) \u2014 a well-chosen Bounded Context often becomes a natural boundary for a separate service, because it already has its own model and its own language."}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"entities-vs-value-objects",children:"Entities vs Value Objects"}),"\n",(0,s.jsx)(n.p,{children:"Two fundamentally different kinds of domain objects, distinguished by whether identity matters."}),"\n",(0,s.jsx)(n.h3,{id:"entities--defined-by-identity",children:"Entities \u2014 Defined by Identity"}),"\n",(0,s.jsx)(n.p,{children:"An Entity is defined by a persistent identity that continues even as its attributes change over time."}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-python",children:'class Customer:\n    def __init__(self, customer_id: str, name: str, email: str):\n        self.customer_id = customer_id   # identity \u2014 this is what makes\n        self.name = name                    # two Customers "the same" or not\n        self.email = email\n\n    def __eq__(self, other):\n        # Equality is based on IDENTITY, not on matching attribute values\n        return isinstance(other, Customer) and self.customer_id == other.customer_id\n\n# Even if name and email both change, this is still "the same customer"\n# because customer_id \u2014 the identity \u2014 hasn\'t changed\ncustomer = Customer("CUST-001", "Alice", "alice@old-email.com")\ncustomer.email = "alice@new-email.com"\n# Still the same Customer, by identity, despite the attribute change\n'})}),"\n",(0,s.jsx)(n.h3,{id:"value-objects--defined-by-value",children:"Value Objects \u2014 Defined by Value"}),"\n",(0,s.jsx)(n.p,{children:"A Value Object has no identity of its own \u2014 two Value Objects with the same attributes ARE the same, interchangeably. Value Objects should generally be immutable."}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-python",children:'class Money:\n    def __init__(self, amount: float, currency: str):\n        self.amount = amount\n        self.currency = currency\n\n    def __eq__(self, other):\n        # Equality is based on VALUE, not identity\n        return (\n            isinstance(other, Money)\n            and self.amount == other.amount\n            and self.currency == other.currency\n        )\n\n    def add(self, other: "Money") -> "Money":\n        if self.currency != other.currency:\n            raise ValueError("currency mismatch")\n        return Money(self.amount + other.amount, self.currency)   # returns a NEW\n                                                                       # instance \u2014 immutable\n\nprice1 = Money(19.99, "USD")\nprice2 = Money(19.99, "USD")\nprint(price1 == price2)   # True \u2014 same value, fully interchangeable,\n                             # even though they\'re different Python objects\n'})}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:'Quick test: "if I have two of these with identical attributes, are\nthey the same thing, or two DIFFERENT things that happen to look alike?"\n\n  Two Customer records with identical name/email \u2192 still TWO different\n  customers (maybe a father and son with the same name) \u2192 Entity\n\n  Two $19.99 USD amounts \u2192 completely interchangeable, no meaningful\n  difference \u2192 Value Object\n\nCommon Value Objects in real domains: Money, Address, DateRange,\nEmail, PhoneNumber, Coordinates \u2014 anything defined entirely by its\nattributes, with no independent identity or lifecycle of its own.\n'})}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"aggregates",children:"Aggregates"}),"\n",(0,s.jsxs)(n.p,{children:["An Aggregate is a cluster of related Entities and Value Objects treated as a single unit for the purpose of data changes, with one designated ",(0,s.jsx)(n.strong,{children:"Aggregate Root"})," controlling access to everything inside."]}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-python",children:'# The Order is the Aggregate Root \u2014 external code interacts with the\n# Order, never directly with OrderLine objects inside it\nclass Order:\n    def __init__(self, order_id: str):\n        self.order_id = order_id\n        self._lines: list[OrderLine] = []      # internal \u2014 not exposed directly\n        self._status = "draft"\n\n    def add_line(self, product_id: str, quantity: int, unit_price: Money):\n        if self._status != "draft":\n            raise ValueError("cannot modify a submitted order")\n        self._lines.append(OrderLine(product_id, quantity, unit_price))\n\n    def submit(self):\n        if not self._lines:\n            raise ValueError("cannot submit an empty order")\n        self._status = "submitted"\n\n    def total(self) -> Money:\n        total = Money(0, "USD")\n        for line in self._lines:\n            total = total.add(line.subtotal())\n        return total\n\nclass OrderLine:                                  # NOT an Aggregate Root \u2014\n    def __init__(self, product_id, quantity, unit_price: Money):   # only reachable\n        self.product_id = product_id                                 # through Order\n        self.quantity = quantity\n        self.unit_price = unit_price\n\n    def subtotal(self) -> Money:\n        return Money(self.unit_price.amount * self.quantity, self.unit_price.currency)\n\n# External code NEVER does this:\n#   order._lines.append(OrderLine(...))     # bypasses Order\'s business rules!\n# It always goes through the Aggregate Root:\norder.add_line("SKU-123", 2, Money(9.99, "USD"))\n'})}),"\n",(0,s.jsxs)(n.p,{children:['Why this matters: the Aggregate Root is the single place business rules and invariants are enforced (like "cannot modify a submitted order" above). If external code could reach into ',(0,s.jsx)(n.code,{children:"_lines"})," directly, that invariant could be silently violated from anywhere in the codebase. This is also the natural transaction boundary \u2014 in most systems, one Aggregate is saved/loaded as a single atomic unit."]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"domain-services",children:"Domain Services"}),"\n",(0,s.jsx)(n.p,{children:"Some operations don't naturally belong to a single Entity or Value Object \u2014 they involve coordination across multiple domain objects. These live in a Domain Service."}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{className:"language-python",children:"# This operation doesn't naturally belong to Order OR Inventory alone \u2014\n# it coordinates between them\nclass OrderFulfillmentService:\n    def __init__(self, inventory_repository, order_repository):\n        self.inventory_repo = inventory_repository\n        self.order_repo = order_repository\n\n    def fulfill(self, order: Order):\n        for line in order.lines:\n            available = self.inventory_repo.check_stock(line.product_id)\n            if available < line.quantity:\n                raise InsufficientStockError(line.product_id)\n\n        for line in order.lines:\n            self.inventory_repo.reserve_stock(line.product_id, line.quantity)\n\n        order.mark_fulfilled()\n        self.order_repo.save(order)\n"})}),"\n",(0,s.jsxs)(n.p,{children:["A Domain Service is different from the Application/Infrastructure Services covered elsewhere in this course (like ",(0,s.jsx)(n.code,{children:"UserService"})," in the Echo course's database page) \u2014 a Domain Service specifically encapsulates ",(0,s.jsx)(n.em,{children:"business logic"})," that spans multiple domain objects, not application orchestration or infrastructure plumbing."]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"when-ddd-is-and-isnt-worth-it",children:"When DDD Is (and Isn't) Worth It"}),"\n",(0,s.jsx)(n.pre,{children:(0,s.jsx)(n.code,{children:"DDD's tactical patterns (Entities, Value Objects, Aggregates) add real\nstructural overhead \u2014 more classes, more explicit boundaries, more\nupfront design conversation with domain experts.\n\nWorth it when:\n  The business domain has genuinely complex rules and behavior\n  (insurance underwriting, financial trading, supply chain logistics,\n  healthcare \u2014 anywhere \"the business logic IS the hard part\")\n  Multiple teams need to work in the same domain without constantly\n  colliding over an ambiguous shared model\n  The domain is expected to evolve significantly over the project's\n  life, and getting the model right matters for long-term maintainability\n\nOverkill when:\n  The application is largely CRUD \u2014 create, read, update, delete a\n  record, with little genuine business logic beyond simple validation\n  A small team, well-understood problem, short expected lifetime\n  You'd spend more time designing Bounded Contexts than the entire\n  business logic actually contains\n\nThis is the same YAGNI/KISS judgment call from file 04, applied\nspecifically to domain modeling \u2014 DDD's ceremony should be justified\nby genuine domain complexity, not applied as a default starting point\nfor every project.\n"})}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"tips",children:"Tips"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsx)(n.li,{children:"Build the ubiquitous language WITH domain experts, in conversation \u2014 don't invent terminology unilaterally as an engineer and hope it matches how the business actually thinks."}),"\n",(0,s.jsx)(n.li,{children:'The Entity vs Value Object test is simple and reliable: "if two of these have identical attributes, are they the same thing or two different things?" \u2014 identity means Entity, pure value means Value Object.'}),"\n",(0,s.jsx)(n.li,{children:"Keep Value Objects immutable \u2014 operations return a new instance rather than mutating in place, which eliminates a whole class of subtle bugs from shared mutable state."}),"\n",(0,s.jsx)(n.li,{children:"External code should only ever modify an Aggregate through its Root \u2014 if you find yourself reaching into an Aggregate's internals directly, that's a sign an invariant is at risk of being silently violated somewhere."}),"\n",(0,s.jsx)(n.li,{children:"Don't reach for full DDD ceremony on a simple CRUD app \u2014 match the investment in domain modeling to the actual complexity of the business rules involved."}),"\n"]}),"\n",(0,s.jsx)(n.hr,{}),"\n",(0,s.jsx)(n.h2,{id:"summary",children:"Summary"}),"\n",(0,s.jsxs)(n.ul,{children:["\n",(0,s.jsx)(n.li,{children:"DDD closes the gap between business understanding and code structure by modeling the domain directly, using the business's own vocabulary (the ubiquitous language)."}),"\n",(0,s.jsx)(n.li,{children:"Bounded Contexts acknowledge that the same term can mean different things in different parts of a large system \u2014 each context gets its own tailored model, connected via explicit translation at the boundaries."}),"\n",(0,s.jsx)(n.li,{children:"Entities are defined by identity (persists through attribute changes); Value Objects are defined by value (interchangeable if attributes match) and should be immutable."}),"\n",(0,s.jsx)(n.li,{children:"Aggregates cluster related Entities/Value Objects under a single Aggregate Root, which enforces business invariants and serves as the natural transaction boundary."}),"\n",(0,s.jsx)(n.li,{children:"Domain Services hold business logic that spans multiple domain objects and doesn't naturally belong to any single one."}),"\n",(0,s.jsx)(n.li,{children:"DDD's structural ceremony is worth its cost for genuinely complex business domains \u2014 it's overkill for simple CRUD applications; match the investment to actual domain complexity."}),"\n"]})]})}function u(e={}){let{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,s.jsx)(n,{...e,children:(0,s.jsx)(c,{...e})}):c(e)}},8453(e,n,t){t.d(n,{R:()=>r,x:()=>o});var i=t(6540);let s={},a=i.createContext(s);function r(e){let n=i.useContext(a);return i.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function o(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:r(e.components),i.createElement(a.Provider,{value:n},e.children)}}}]);